[237] = { en = "In Defense of the King's Lands", tier = 1,
  t = "Ter verdediging van het land van de koning",
  d = "Mountaineer Cobbleflint zei alleen maar goede dingen over jou, $r. Daarom geef ik je een opdracht die heel erg belangrijk is. We moeten de troggs die ons land binnenvallen onder druk houden. Dat moet zo blijven tot onze dwergse broeders terugkomen van het front van de Alliance.$b$bGa naar de heuvels in het zuiden en dood 10 Stonesplinter Skullthumpers en 10 Stonesplinter Seers. Met jouw aanvallen winnen we wat tijd. Kom terug als je opdracht klaar is.",
  o = "Mountaineer Gravelgaw in de zuidelijke wachttoren wil dat je 10 Stonesplinter Skullthumpers en 10 Stonesplinter Seers doodt en daarna bij hem terugkomt.",
  p = "We hebben meer tijd nodig, $r. Je opdracht is: dood 10 Stonesplinter Skullthumpers en 10 Stonesplinter Seers. Houd de vijand onder druk tot we versterking krijgen. Dit is geen tijd om niets te doen.",
  c = "Je hebt je opdracht goed uitgevoerd, $R. De koning zelf zou trots zijn.$B$BMaar de versterking die ons beloofd was, is nooit gekomen. Het front van de Alliance is blijkbaar een zee van donkerrood, van het bloed van onze gevallen broeders. Het nieuws over de verliezen laat een bittere smaak in je mond achter. Maar hun dood mag niet voor niets zijn. In deze sombere tijden moeten we ons verzamelen en de Alliance weer glorie brengen.$B$BPraat met Mountaineer Wallbang voor een nieuwe opdracht. We hebben je nu harder nodig dan ooit.",
  g = { {"binnenvallen", "invade"}, {"broeders", "brethren (broeder)"}, {"front", "front (of a war)"}, {"versterking", "reinforcements"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"beloofd", "promised (beloven)"}, {"blijkbaar", "apparently"}, {"gevallen", "fallen (in battle)"}, {"verliezen", "losses (verlies)"}, {"bittere", "bitter (bitter)"}, {"sombere", "grim, gloomy (somber)"}, {"ons verzamelen", "to rally, gather together (zich verzamelen)"}, {"glorie", "glory"} },
},

[263] = { en = "In Defense of the King's Lands", tier = 1,
  t = "Ter verdediging van het land van de koning",
  d = "De Mountaineers zeggen dat je heel dapper en bekwaam bent, $N. We hebben hier een $r zoals jij nodig. Het probleem met de troggs wordt niet beter. De reserves zijn naar het front geroepen en we staan hier helemaal alleen. Maar nu er een ervaren $c bij ons is, kunnen we zien wat je kunt.$b$bGa erop uit en dood 10 Stonesplinter Shaman en 10 Stonesplinter Bonesnappers. Laat maar zien of je je reputatie waarmaakt, Troggdoder.",
  o = "Mountaineer Wallbang in de zuidelijke wachttoren wil dat je 10 Stonesplinter Shaman en 10 Stonesplinter Bonesnappers doodt.",
  p = "Ben je nu al terug? Voor het geval ik niet duidelijk was: je moet 10 Stonesplinter Shaman en 10 Stonesplinter Bonesnappers doden, $N. Pak ze nu maar aan, Troggdoder!",
  c = "Ik wist het meteen toen ik je zag, $N: jij zou Ironforge trots maken. Je hebt koning Magni goed gediend. Je hebt laten zien dat je het koninkrijk trouw helpt. Misschien moet je nu met de kapitein praten. Misschien geeft hij je een belangrijkere taak.$B$BIk groet je, $N.",
  g = { {"bekwaam", "capable, skilled"}, {"reserves", "reserves (troops)"}, {"geroepen", "called (roepen)"}, {"ervaren", "experienced"}, {"reputatie", "reputation"}, {"waarmaakt", "live up to (waarmaken)"}, {"Troggdoder", "Trogg-Slayer"}, {"voor het geval", "in case"}, {"gediend", "served (dienen)"}, {"koninkrijk", "kingdom"}, {"trouw", "loyal, loyally"}, {"groet", "salute, greet (groeten)"} },
},

[273] = { en = "Resupplying the Excavation", tier = 1,
  t = "Nieuwe voorraden voor de opgraving",
  d = "Maar het is nog niet te laat. Je mag gerust Huldar gaan zoeken. Hij kan nog niet erg ver zijn. Miran en Saean zijn sterk, maar ze zijn zwaar beladen met die vaten. Daardoor kunnen ze maar langzaam vooruit.$b$bZe nemen de gewone weg naar de opgraving: de stad uit naar het zuiden en dan langs de bocht van het meer.$b$bJe vindt ze vast zonder problemen, tenzij ze er al zijn.",
  o = "Praat met Huldar.",
  c = "Hmf, er is meer nodig dan een hinderlaag van de Dark Irons om de leveringen te stoppen!$b$bMaar Saean... Ik had nooit gedacht dat hij een van hun medestanders was. We werken nu al bijna een jaar met hem samen... Misschien heb ik de tekens gemist.$b$bNou ja, daar denk ik later wel over na.",
  e = "Zoek Huldar, Miran en Saean",
  g = { {"voorraden", "supplies (voorraad)"}, {"opgraving", "excavation, dig"}, {"gerust", "feel free to, by all means"}, {"beladen", "loaded, laden"}, {"vaten", "barrels (vat)"}, {"bocht", "bend, curve"}, {"tenzij", "unless"}, {"hinderlaag", "ambush"}, {"leveringen", "deliveries (levering)"}, {"medestanders", "sympathizers, supporters (medestander)"}, {"tekens", "signs (teken)"} },
},

[298] = { en = "Excavation Progress Report", tier = 1,
  t = "Voortgangsverslag van de opgraving",
  d = "Er moet een verslag over de voortgang naar Thelsamar. Een verslag, en nog een keer mijn verzoek om meer springpoeder! Hier is het verslag. Breng het naar Jern Hornhelm. Hij is onze contactpersoon in Thelsamar.$B$BHet is geen moeilijke taak, maar het moet gebeuren.",
  o = "Breng Ironband's Progress Report naar Jern Hornhelm in Thelsamar.",
  p = "O, een verslag van de opgraving? Heel goed!",
  c = "Bah! Ironband heeft problemen met de troggs. Wil hij dat springpoeder om te graven, of om tegen die beesten van troggs te vechten...$b$bNou ja, hoe dan ook: dat poeder is goed besteed!$b$bMaar het vreemde is: ik heb hem weken geleden al genoeg springpoeder gestuurd. Waar zou dat gebleven zijn...",
  g = { {"voortgang", "progress"}, {"verslag", "report"}, {"verzoek", "request"}, {"springpoeder", "blastpowder, explosive powder"}, {"contactpersoon", "contact (person)"}, {"gebeuren", "happen, be done"}, {"hoe dan ook", "either way, anyway"}, {"besteed", "spent (besteden)"}, {"gebleven", "gone, ended up (blijven)"} },
},

[301] = { en = "Report to Ironforge", tier = 1,
  t = "Een verslag voor Ironforge",
  d = "We hebben toestemming nodig om Ironband meer springpoeder te geven. Je moet zijn verslag naar het hoofdkwartier van de Explorers' League in Ironforge brengen.$B$BHier is het verslag. Geef het aan Prospector Stormpike, en vergeet niet te bukken als je het hebt gegeven. Stormpike wordt snel boos, en hij zal niet blij zijn als hij hoort dat het werk van Ironband zo langzaam gaat.$B$BJe vindt Stormpike in de Assembly of Explorers.",
  o = "Breng Ironband's Progress Report naar Prospector Stormpike.",
  p = "Wij Stormpikes houden er niet van als we gestoord worden voor kleine dingen, $C. Ik hoop dat je nieuws hebt dat mijn kostbare aandacht waard is.",
  c = "Die vervloekte Ironband! Ik heb hem weken geleden een lading springpoeder gestuurd, maar daar zegt hij niets over in dit verslag.$b$bDus... waar is dat springpoeder gebleven?!?",
  g = { {"toestemming", "permission, approval"}, {"hoofdkwartier", "headquarters"}, {"bukken", "to duck"}, {"gestoord", "bothered, disturbed (storen)"}, {"kostbare", "valuable (kostbaar)"}, {"aandacht", "attention"}, {"waard", "worth"}, {"vervloekte", "cursed (vervloekt)"}, {"lading", "load, shipment"} },
},

[302] = { en = "Powder to Ironband", tier = 1,
  t = "Poeder voor Ironband",
  d = "Als Ironband nog steeds springpoeder nodig heeft, dan krijgt hij het, bij Magni! Ik heb de toestemming al vooruit gestuurd met een boodschapper naar Jern Hornhelm in Thelsamar. Hij maakt het poeder en de andere voorraden klaar om naar Ironband te brengen.$B$BEn nog één ding: ik wil dat jij er zelf voor zorgt dat de lading poeder aankomt. De vorige lading is niet aangekomen. Dus blijf scherp en houd je ogen open.",
  o = "Praat met Jern Hornhelm in Thelsamar.",
  c = "Wat? Wil Stormpike dat jij zelf de lading naar Ironband begeleidt?$b$bIk... denk dat dat goed is. Het enige probleem is: ik heb Huldar al gestuurd, met de dragers Miran en Saean. Je hebt ze net gemist. Ze zijn kort geleden vertrokken.",
  g = { {"vooruit", "ahead"}, {"boodschapper", "messenger"}, {"zelf", "yourself, personally"}, {"aankomt", "arrives (aankomen)"}, {"vorige", "previous"}, {"scherp", "sharp"}, {"begeleidt", "escorts, accompanies (begeleiden)"}, {"dragers", "porters (drager)"}, {"gemist", "missed (missen)"}, {"vertrokken", "left (vertrekken)"} },
},

[307] = { en = "Filthy Paws", tier = 1,
  t = "Vieze poten",
  d = "De Silver Stream Mine in het oosten is al lang geleden leeg geraakt. De Miners' League heeft er een opslagplaats van gemaakt. Maar nu zijn er kobolds ingetrokken, en ze zitten met hun vieze poten aan goed dwergengereedschap!$B$BWe jagen dat ongedierte er snel genoeg uit. Maar de League wil dat iemand hun spullen uit de mijn haalt, voordat wij krijgers daar naar binnen stampen en dingen kapotmaken. Het wordt een zware tocht onder de grond. Misschien wil je kameraden aan je zijde.$B$BDe spullen liggen in Miners' League Crates, overal in de mijn. Succes.",
  o = "Ga naar de Silver Stream Mine en verzamel 4 ladingen Miners' Gear.$B$BGa terug naar Mountaineer Stormpike.",
  p = "Heb je die Miners' Gear, $N?",
  c = "Heb je daar veel kobolds gezien? Ik kan niet wachten op het bevel om ze uit de mijn te verjagen. Als ik denk aan hun smerige handen die in onze mijn rondgraaien, gaat mijn maag ervan rommelen!",
  g = { {"vieze", "filthy, dirty (vies)"}, {"poten", "paws (poot)"}, {"opslagplaats", "storage depot"}, {"ingetrokken", "moved in (intrekken)"}, {"gereedschap", "tools"}, {"ongedierte", "vermin"}, {"stampen", "stomp, tromp"}, {"kameraden", "comrades (kameraad)"}, {"aan je zijde", "at your side"}, {"bevel", "order, command"}, {"verjagen", "drive away, chase out"}, {"smerige", "grimy, filthy (smerig)"}, {"rondgraaien", "grab around, claw around"}, {"rommelen", "rumble"} },
