[309] = { en = "Protecting the Shipment", tier = 1,
  t = "De lading beschermen",
  d = "Ben je klaar om te gaan, $n?$b$bEerst moeten we dit poeder naar Ironband brengen. Het is veel om te dragen, en het kan hier in de buurt gevaarlijk zijn. En wie weet wat de Dark Irons nog meer voor me van plan zijn.$b$bIk voel me een stuk beter als jij meegaat.",
  o = "Zorg dat Miran en de lading bij de opgraving aankomen. Vertel het daarna aan Prospector Ironband.",
  c = "O, het Licht zij dank, het poeder is er! Maar je brengt ook zorgwekkend nieuws. Stel je voor: de Dark Irons hebben medestanders die zulk materiaal voor hun gemene plannen kunnen krijgen.$b$bDaar moet iemand anders maar over nadenken, een andere keer. Ik moet dit poeder goed gebruiken.",
  e = "Begeleid Miran naar de opgraving",
