[385] = { en = "Crocolisk Hunting", tier = 1,
  t = "Jagen op krokolisken",
  d = "Veel jagers komen naar Loch Modan om op onze beroemde krokolisken te jagen. Er zijn altijd handelaars die krokoliskhuiden zoeken voor kleding of pantser. En er zijn ook mensen die hun vlees lekker vinden.$b$bWe handelen er een beetje in, maar niet veel. De krokolisken zijn namelijk woest, en ze hebben zich stevig vastgezet op de eilanden in het meer. Maar laat je daardoor niet tegenhouden. Het is echt een belevenis om te worstelen met de kaken van die beesten.$b$bNou, die ene keer...",
  o = "Haal 5 stukken Crocolisk Meat en 6 Crocolisk Skins voor Marek Ironheart in de Farstrider Lodge.",
  p = "Heb ik je al verteld over die keer dat ik bijna mijn hand verloor aan een van de krokolisken? Het was een gemeen rotbeest, met tanden als messen. Maar ik had geluk... Ik klemde de kaak van dat beest dicht met mijn mes. Dat mes ligt hier nog ergens...",
  c = "Nou, dit zijn prachtige exemplaren die je hebt verzameld, $N. Goed geld voor materiaal van hoge kwaliteit, dat is zeker.",
