},

[454] = { en = "After the Ambush", tier = 1,
  t = "Na de hinderlaag",
  d = "Voor deze... zaak brachten we de vaten met poeder in een paar tochten heen en weer. Nu moeten we het werk verdelen. Miran neemt de vaten mee en ik pas op de andere.$b$bIk vind het niet veilig als Miran de rest van de lading alleen vervoert. Als hij klaar is om te gaan, kun jij hem misschien begeleiden op zijn volgende tocht?",
  o = "Praat met Miran.",
