[1339] = { en = "Mountaineer Stormpike's Task", tier = 1,
  t = "De taak van Mountaineer Stormpike",
  d = "Ik hoor dat Mountaineer Stormpike een boodschapper zoekt. Iemand die een stukje voor hem reist. Wat denk je ervan? Ben jij de $r voor deze klus?$B$BZo ja, dan vind je Stormpike boven in de noordelijke wachttoren.",
