[2038] = { en = "Bingles' Missing Supplies", tier = 1,
  t = "De verloren spullen van Bingles",
  d = "Eerst stortte ik al neer in het meer. En toen vielen troggs van het eiland hier vlakbij me ook nog aan! Ze stalen mijn gereedschap en mijn speciale Blastenheimer Blastencapper-explosieven. Zonder gyrocopter en zonder explosieven maakt de beweging geen enkele kans!$B$BHaal mijn gereedschap terug en zoek mijn Blastencapper-explosieven, $N. Voor Gnomeregan!",
  o = "Zoek de spullen van Bingles en breng ze terug:$B$BBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer en Bingles' Blastencapper.",
  p = "$N! Waar zijn mijn spullen?!",
  c = "Je hebt de beweging een grote dienst bewezen, $N. De troggs en lepragnomen die Gnomeregan overspoelen, zullen snel de volle klap van een gnomische luchtaanval voelen!",
  g = { {"stortte neer", "crashed (neerstorten)"}, {"vlakbij", "nearby"}, {"stalen", "stole (stelen)"}, {"gereedschap", "tools"}, {"explosieven", "explosives (explosief)"}, {"beweging", "movement"}, {"geen enkele", "not a single, no"}, {"een dienst bewezen", "did a service (bewijzen)"}, {"lepragnomen", "leper gnomes"}, {"overspoelen", "infest, overrun"}, {"klap", "blow, brunt"}, {"luchtaanval", "air assault"} },
