[257] = { en = "A Hunter's Boast", tier = 1,
  t = "De opschepperij van een jager",
  d = "Denk je dat je net zo slim bent als Daryl the Bold? Dat dacht ik niet! Maar je mag het natuurlijk proberen. Hier is een uitdaging die vast te moeilijk voor je is. Voel je dus niet te slecht als je het niet aankunt.$b$bEen zwerm gieren heeft hier in Loch Modan een nest gemaakt. Probeer eens een paar van die beesten neer te halen. Weet je wat? Als je binnen vijftien minuten mijn uitdaging haalt, geef ik je mijn boog of mijn geweer.$b$b<Hij bekijkt je met minachting.>$b$bJe hebt toch al niet veel te verliezen, zo te zien.",
  o = "Dood 6 Mountain Buzzards en ga binnen 15 minuten terug naar Daryl the Youngling in de Farstrider Lodge.",
  p = "Geen geluk? Voel je niet te slecht, $N...$B$BNiet iedereen kan mij zijn.",
  c = "Wat? Gelukt?$B$BLuister naar mij, $Nama: laat het je niet naar je hoofd stijgen. Ik bedoel, elke ongeschoren jongen met een boog had zulke... kleine exemplaren kunnen doden. En ik hoop dat je het niet te leuk vindt om de gieren te doden, hè? We willen niet dat ze uitsterven.$B$BNou, eh... Niemand zal ooit kunnen zeggen dat Daryl the Bold zich niet aan zijn woord houdt.",
  g = { {"opschepperij", "boasting, bragging"}, {"uitdaging", "challenge"}, {"aankunt", "can handle (aankunnen)"}, {"zwerm", "flock"}, {"gieren", "buzzards, vultures (gier)"}, {"geweer", "gun, rifle"}, {"minachting", "contempt, dismissiveness"}, {"verliezen", "lose"}, {"naar je hoofd stijgen", "go to your head (stijgen)"}, {"ongeschoren", "unshaven"}, {"exemplaren", "specimens (exemplaar)"}, {"uitsterven", "become extinct"}, {"zich aan zijn woord houdt", "keeps his word (houden)"} },
},

[217] = { en = "In Defense of the King's Lands", tier = 1,
  t = "Ter verdediging van het land van de koning",
  d = "$N, onze verkenners weten nu wie de leider is van deze nieuwe inval van de troggs. Het lijkt erop dat de beesten in Loch Modan een stamhoofd volgen dat Grawmug heet. Maar Grawmug wordt zwaar bewaakt. Zijn twee beste wachters, Gnasher en Brawler, gaan nooit bij hem weg.$b$bAls je denkt dat je het waard bent, $N, wil ik dat jij de aanslag op Grawmug en zijn twee boeven leidt. Als de leiders van de troggs dood zijn, hebben we misschien een kans om die beesten terug de grond in te duwen.",
  o = "Dood de leider van de troggs, Grawmug, en zijn twee wachters, Gnasher en Brawler. Ga daarna terug naar Captain Rugelfuss in de zuidelijke wachttoren.",
  p = "Grawmug en zijn twee wachters, Gnasher en Brawler, leven nog. Je opdracht is pas klaar als ze alle 3 dood zijn. Het rijk van de dwergen rekent op je, $N.",
  c = "Uitstekend, $N! Je hebt Loch Modan hoop gegeven. Nu Grawmug dood is, hebben we een betere kans om de troggs uit het land te verdrijven.",
  g = { {"verkenners", "scouts (verkenner)"}, {"inval", "incursion, raid"}, {"stamhoofd", "chieftain"}, {"bewaakt", "guarded (bewaken)"}, {"wachters", "guards (wachter)"}, {"waard", "worthy"}, {"aanslag", "assassination, attack"}, {"boeven", "thugs (boef)"}, {"rijk", "empire, realm"}, {"rekent op", "counts on (rekenen op)"}, {"uitstekend", "excellent"}, {"verdrijven", "drive out, eliminate"} },
},

[258] = { en = "A Hunter's Challenge", tier = 1,
  t = "De uitdaging van een jager",
  d = "$nath, toch? Ik zie dat je barst van trots omdat je de eerste test hebt gehaald, hè? Zoals ik al zei: het is geen grote prestatie.$b$bJe moet het eens proberen met de jacht op zwijnen. Geloof me, dit is geen zwijnenjacht zoals in Coldridge Valley, dus pas goed op met ze. Deze keer geef ik je maar twaalf minuten.$b$bVoel je niet slecht als het mislukt. Als het je lukt, geef ik je het shirt dat ik aanheb!$b$bHeb ik je ooit het verhaal verteld van hoe ik mijn beroemde litteken kreeg? Nee? Het was twee jaar geleden...",
  o = "Dood 5 Elder Mountain Boars en ga binnen 12 minuten terug naar Daryl the Youngling in de Farstrider Lodge.",
  p = "Het is heel normaal dat je medelijden met jezelf hebt als iemand die zo nieuw is in deze wereld beter is dan jij. Je moet je niet slecht voelen, $N.$B$BHm? Heb ik je naam verkeerd gezegd?",
  c = "Je ziet er wat gehavend uit. De zwijnen hebben je vast wat problemen gegeven, hè? Geen zorgen, ik zal niemand iets vertellen over je moeite. Ik kan me voorstellen hoe moeilijk het voor je moet zijn, ook zonder de beschuldigingen van roddelende tongen.$B$BO! Heb je de zwijnen echt gedood? Ik... nou, dat wil zeggen... dat wil zeggen, het verbaast me niets! Elk kind had -- een weddenschap?$B$BWelke weddenschap?",
  g = { {"barst van trots", "bursting with pride (barsten)"}, {"prestatie", "feat, achievement"}, {"zwijnen", "boars (zwijn)"}, {"mislukt", "fails (mislukken)"}, {"aanheb", "have on, wear (aanhebben)"}, {"litteken", "scar"}, {"medelijden", "pity"}, {"gehavend", "battered, worse for wear"}, {"moeite", "struggle, trouble"}, {"voorstellen", "imagine (zich voorstellen)"}, {"beschuldigingen", "accusations (beschuldiging)"}, {"roddelende", "gossiping (roddelen)"}, {"verbaast", "surprises (verbazen)"}, {"weddenschap", "bet"} },
