[161] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Als mijn vermoeden klopt, is dit een soort explosief poeder. Een explosievenexpert moet het onderzoeken, zodat we weten waar we mee te maken hebben. Ashlan Stonesmirk werd ingedeeld bij het regiment dat Dun Modr en de Thandol Span bewaakt. Ik wil dat je een zware en gevaarlijke reis maakt, $N.$b$bReis door de Algaz Gate, volg de weg door de Wetlands en zoek Stonesmirk in Dun Modr. Luister naar mijn raad: blijf op de wegen en stop voor niets!",
  o = "Chief Engineer Hinderweir wil dat je het vreemd ruikende poeder naar Ashlan Stonesmirk brengt, de explosievenexpert in Dun Modr.",
  p = "Zei je iets, jongen? Ik hoor verdorie niks, alleen het piepen in mijn oren. Zeg, wat heb je daar?",
  c = "Ah, de oude Hinderweir doet er verstandig aan om zich zorgen te maken.",
  g = { {"duistere", "dark (duister)"}, {"dreiging", "threat"}, {"vermoeden", "suspicion"}, {"explosief", "explosive"}, {"explosievenexpert", "explosives expert"}, {"onderzoeken", "analyze, examine"}, {"te maken hebben met", "be dealing with"}, {"ingedeeld", "assigned (indelen)"}, {"regiment", "regiment"}, {"raad", "advice"}, {"ruikende", "smelling (ruiken)"}, {"verdorie", "blast it, bloody"}, {"piepen", "ringing, beeping"}, {"verstandig", "wise, sensible"} },
},

[199] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Je neemt een monster van het vreemd ruikende poeder.",
  o = "Ga terug naar Chief Engineer Hinderweir en laat hem de aanwijzing zien die je hebt gevonden.",
