},

[250] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "De sterren zij dank, er is iemand die zich zorgen maakt over de veiligheid van de dam. Eerst werd de Thandol Span vernietigd en daarna werd Dun Modr geplunderd! Ik twijfel er niet aan dat de dam het volgende doelwit van de Dark Irons wordt. De meeste bewakers van hier zijn naar het front van de Alliance gestuurd, ook mijn beste inspecteur.$b$bDaarom heb ik jou nodig, $N. Ik zag een paar Dark Iron Sappers rondhangen bij de oostelijke helling van de dam. Onderzoek het gebied en breng een aanwijzing mee.",
  o = "Onderzoek het gebied bij de oostelijke helling van de dam. Breng Chief Engineer Hinderweir een aanwijzing die kan laten zien wat de Dark Iron Dwarves van plan zijn.",
  c = "In het verdacht uitziende vat zit een vreemd ruikend poeder.",
  g = { {"de sterren zij dank", "thank the stars"}, {"veiligheid", "well-being, safety"}, {"vernietigd", "destroyed (vernietigen)"}, {"geplunderd", "pillaged (plunderen)"}, {"twijfel", "doubt (twijfelen)"}, {"doelwit", "target"}, {"bewakers", "guards, security (bewaker)"}, {"rondhangen", "mill about, hang around"}, {"oostelijke", "eastern (oostelijk)"}, {"helling", "ramp, slope"}, {"onderzoek", "investigate (onderzoeken)"}, {"verdacht", "suspicious"} },
},

[274] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Dit is geen gewoon springpoeder. Kijk naar die kleine zilveren kristallen. En die aparte geur! Het is zo klaar als een klontje: dit is Seaforium Powder. Seaforium is op zich vrij onschuldig. Maar als het nat wordt, kan het Ironforge uit de berg blazen.$b$bJe kunt de chemische reactie onschadelijk maken door vier dingen te mengen: lurkergif, gemalen Mo'Grosh-kristal, een krokolisktraan en dit ontmantelingscolloïde. Vertel het nu aan Hinderweir, voordat het te laat is!",
  o = "Ashlan Stonesmirk wil dat je teruggaat naar Chief Engineer Hinderweir en hem over de nieuwe ontdekking vertelt.",
  p = "Wat breng je mee van Ashlan?",
  c = "Een ontmantelingscolloïde? Voor Seaforium? O hemel!",
  g = { {"kristallen", "crystals (kristal)"}, {"aparte", "distinct (apart)"}, {"zo klaar als een klontje", "clear as daylight"}, {"op zich", "in itself"}, {"onschuldig", "harmless"}, {"chemische", "chemical (chemisch)"}, {"onschadelijk maken", "defuse, make harmless"}, {"mengen", "mix"}, {"gemalen", "crushed, ground (malen)"}, {"krokolisktraan", "crocolisk tear"}, {"ontmantelingscolloïde", "disarming colloid"}, {"o hemel", "oh heavens"} },
},

[278] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Begin meteen met het verzamelen van de ontmantelende spullen, $N. Lurkergif vind je bij de spinnen die van nature in Loch Modan leven. Krokolisktranen vind je hier ook in het meer. Maar een Mo'Grosh-kristal is heel moeilijk te krijgen. De ogers in het noordoosten halen ze uit hun mijn, maar de kristallen zijn heel zeldzaam.$b$bWe moeten klaar zijn om een aanval van de Dark Irons onschadelijk te maken! Kom terug als je de nodige spullen hebt verzameld, dan maak ik het mengsel klaar.",
  o = "Chief Engineer Hinderweir wil dat je Lurker Venom, een Mo'grosh Crystal en een Crocolisk Tear verzamelt.",
  p = "Heb je de spullen die we nodig hebben? Er is geen tijd te verliezen!!",
  c = "Net op tijd, $N!",
  g = { {"meteen", "immediately"}, {"ontmantelende", "disarming (ontmantelen)"}, {"lurkergif", "lurker venom"}, {"van nature", "naturally, native"}, {"krokolisktranen", "crocolisk tears (krokolisktraan)"}, {"ogers", "ogres (oger)"}, {"zeldzaam", "rare"}, {"onschadelijk maken", "defuse"}, {"nodige", "needed (nodig)"}, {"mengsel", "mixture"}, {"geen tijd te verliezen", "no time to lose"} },
},

[280] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Eerder vandaag zag ik een paar Dark Iron Insurgents met een groot vat naar de dam zwemmen. Er waren geen Mountaineers om ze tegen te houden! Ik ben bang dat ze het Seaforium onder aan de dam hebben gezet. Het kan elk moment ontploffen! Laat me al deze ingrediënten mengen tot de Disarming Mixture. Zo.$b$bNeem nu dit mengsel en roer het door het vat, voordat het te laat is! Snel!",
  o = "Chief Engineer Hinderweir wil dat je naar de onderkant van de dam zwemt. Zoek het vat met poeder en roer de Disarming Mixture erdoor, zodat er geen ontploffing komt.",
  p = "Het deksel van het vat draait langzaam los.",
  c = "Het vat bruist een beetje terwijl de Disarming Mixture erin zakt.",
  g = { {"eerder", "earlier"}, {"tegen te houden", "to stop (tegenhouden)"}, {"onder aan", "at the base of"}, {"ontploffen", "explode"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"roer", "stir (roeren)"}, {"onderkant", "bottom, base"}, {"ontploffing", "explosion"}, {"deksel", "lid, top"}, {"draait los", "twists off (losdraaien)"}, {"bruist", "fizzles (bruisen)"}, {"zakt", "settles, sinks (zakken)"} },
},

[297] = { en = "Gathering Idols", tier = 1,
  t = "Afgodsbeelden verzamelen",
  d = "Kort geleden, vlak voordat de troggs op de opgraving opdoken, hadden we een groot aantal vreemde, gehouwen afgodsbeelden gevonden. Maar we hadden geen kans om ze te bestuderen, want vlak daarna joegen de troggs ons weg uit de ruïnes! En die beelden hebben een vreemd effect op de troggs. Ze worden er razend van!$B$BBreng me 8 beelden. Ik wil ze bestuderen, en ik wil dat de troggs ze niet meer hebben! Je vindt de beelden bij de troggs die de opgraving overspoelen.",
  o = "Breng Magmar Fellhew 8 Carved Stone Idols.",
  p = "Heb je die beelden? We moeten ze bestuderen en ons onderzoek aan Ironforge melden!",
  c = "Je hebt ze! Goed gedaan, $N!$B$BEn je ziet er niet al te gehavend uit, ook al lopen die razende troggs hier rond. Ik ga je in de gaten houden... je bent veelbelovend.",
  g = { {"afgodsbeelden", "idols (afgodsbeeld)"}, {"opdoken", "surfaced, appeared (opduiken)"}, {"gehouwen", "carved (in stone) (houwen)"}, {"bestuderen", "study"}, {"joegen", "chased (jagen)"}, {"ruïnes", "ruins (ruïne)"}, {"razend", "berserk, furious"}, {"overspoelen", "infest, overrun"}, {"onderzoek", "findings, research"}, {"gehavend", "worse for wear"}, {"in de gaten houden", "keep an eye on"}, {"veelbelovend", "promising"} },
},

[436] = { en = "Ironband's Excavation", tier = 1,
  t = "De opgraving van Ironband",
  d = "Prospector Ironband leidt een opgraving van oude ruïnes ten oosten van het meer. De laatste tijd gaat het werk langzaam, vooral als je kijkt naar alle voorraden die we hem hebben gestuurd.$B$BIronband is een stevige, eerlijke dwerg die resultaten belangrijk vindt. Daarom ben ik bang dat er krachten tegen hem werken.$B$BGa naar Ironband's Excavation en praat met Magmar Fellhew. Hij regelt de details van de opgraving en weet vast waarom het werk zo traag gaat.$B$BOm bij de opgraving te komen, ga je om de zuidpunt van het meer heen en dan naar het oosten.",
  o = "Praat met Explorer Fellhew.",
  c = "Jern wil weten waarom het zo traag gaat, hè?$b$bIronband maakt zijn nieuwste verslag klaar, met alle details. Maar dit kan ik je wel vertellen:$b$bHet komt door de troggs!!",
  g = { {"leidt", "heads, leads (leiden)"}, {"ten oosten van", "east of"}, {"vooral", "especially"}, {"stevige", "stout, sturdy (stevig)"}, {"resultaten", "results (resultaat)"}, {"krachten", "forces (kracht)"}, {"regelt", "manages (regelen)"}, {"traag", "slow"}, {"zuidpunt", "southern tip"}, {"nieuwste", "latest (nieuw)"} },
},

[255] = { en = "Mercenaries", tier = 1,
  t = "Huurlingen",
  d = "Twee maanden wachten we, alleen om uit Ironforge te horen dat we een handjevol soldaten krijgen voor onze eigen verdediging. En dan nog eens twee maanden tot ze er zijn! Het is al erg genoeg dat onze stad niet beschermd wordt. Maar de opgraving en de dam -- de dam! -- kunnen ook aangevallen worden.$b$bIk heb dus geen keus, zo te zien. Ik heb huurlingen nodig.$b$bWat dacht je van jou? Je lijkt me geschikt, $c. Een groep ogers heeft een kamp opgezet in het noordoosten van het meer. Misschien kun je wat anderen zoeken en helpen om dat gevaar voor onze stad weg te halen?",
  o = "Magistrate Bluntnose van Thelsamar heeft je ingehuurd om 4 Mo'grosh Ogres, 4 Mo'grosh Brutes en 4 Mo'grosh Enforcers te doden.",
  p = "Heb je al geluk gehad?",
  c = "Ah, dit is uitstekend nieuws! Ik en de mensen van Thelsamar zijn heel dankbaar voor je werk. En nog beter: als we het probleem met de ogers kunnen oplossen, kunnen we ons richten op die vervloekte troggs.",
  g = { {"huurlingen", "mercenaries (huurling)"}, {"handjevol", "handful"}, {"verdediging", "defense"}, {"erg genoeg", "bad enough"}, {"beschermd", "protected (beschermen)"}, {"keus", "choice"}, {"geschikt", "suitable, a likely sort"}, {"opgezet", "set up (opzetten)"}, {"ingehuurd", "hired (inhuren)"}, {"dankbaar", "grateful"}, {"ons richten op", "shift our focus to (zich richten op)"} },
},

[271] = { en = "Vyrin's Revenge", tier = 1,
  t = "De wraak van Vyrin",
  d = "Je hebt zeker geen zin in een beetje wraak op Zijne Dapperheid? Daryl heeft wel wat talent, al doet het me pijn om dat te zeggen.$b$bEen jaar geleden jaagden de jagers van de Farstrider Lodge op een grote beer, maar niemand had geluk. Dus dacht Daryl dat hij het zelf eens zou proberen. Het enige wat hij eraan overhield, was dat lelijke litteken boven zijn oog.$b$bDood de beer. Dan is zelfs Daryl voor één keer sprakeloos, dat weet ik zeker.$b$bDe beer, Ol' Sooty, vind je bij zijn hol in de heuvels boven Thelsamar.",
  o = "Dood Ol' Sooty en laat je werk daarna zien aan Daryl the Youngling in de Farstrider Lodge.",
  p = "Ah, $N! Ben je nu al terug? Je bent vast weer aan het jagen geweest? Maak je geen zorgen als het soms tegenzit. Op de lange duur word je er beter van!$B$B... Veel slechter kun je toch niet worden...",
  c = "Eh... wat is dit? Het hoofd van een beer, zo te zien.$B$B<Zonder het te merken gaat hij met een vinger langs zijn litteken.>$B$BNou, dat is een interessante vangst die je daar hebt. Het kan toch niet die beer van toen zijn...$B$B<Hij maakt zijn zin niet af en begint zichtbaar te trillen.>$B$BO, haal dat weg, haal het weg! Haal dat griezelige ding hier weg!",
  g = { {"wraak", "revenge, payback"}, {"zin", "desire, wish (zin hebben in)"}, {"Zijne Dapperheid", "His Boldness"}, {"overhield", "was left with (overhouden)"}, {"litteken", "scar"}, {"sprakeloos", "speechless"}, {"hol", "lair, den"}, {"tegenzit", "goes badly (tegenzitten)"}, {"op de lange duur", "in the long run"}, {"merken", "notice"}, {"vangst", "catch, kill"}, {"zichtbaar", "visibly"}, {"trillen", "shake, tremble"}, {"griezelige", "grisly, creepy (griezelig)"} },
},

[283] = { en = "A Dark Threat Looms", tier = 1,
  t = "Een duistere dreiging",
  d = "Het vat bruist een beetje.",
  o = "Het lijkt erop dat de Disarming Mixture werkt. Ga terug naar Chief Engineer Hinderweir om het goede nieuws te melden.",
  c = "Heel erg bedankt, $N!! Je hebt de Stonewrought Dam gered! Zonder jouw hulp hadden de terroristen van de Dark Irons dit machtige monument zeker vernietigd. Je hebt het koninkrijk en de Alliance trots gemaakt, dappere $C.$b$bDe dam is weer veilig. . . in elk geval voorlopig. . . .",
  g = { {"bruist", "fizzles (bruisen)"}, {"het lijkt erop", "it seems"}, {"melden", "report"}, {"gered", "saved (redden)"}, {"terroristen", "terrorists (terrorist)"}, {"machtige", "mighty (machtig)"}, {"monument", "landmark, monument"}, {"vernietigd", "destroyed (vernietigen)"}, {"in elk geval", "at least"}, {"voorlopig", "for the time being"} },
},

[531] = { en = "Vyrin's Revenge", tier = 1,
  t = "De wraak van Vyrin",
  d = "Licht! Breng zulke dingen niet in de Lodge... het is onhygiënisch, onuitsprekelijk, on... on... onhygiënisch!$b$bHaal het hier gewoon weg, wil je? Echt niemand wil je bloederige kleine trofee zien!",
  o = "Breng Ol' Sooty's head naar Vyrin Swiftwind in de Farstrider Lodge.",
  p = "Goed gedaan, $N! We hebben het hem echt laten zien! Geef me het hoofd maar, dan zorg ik ervoor.",
  c = "Bedankt dat je me hebt geholpen met mijn kleine plan, $N. Ik wilde al maanden wraak nemen op die verwaande, arrogante jongen, en volgens mij is het ons aardig gelukt! Hier, neem dit. Je hebt het verdiend.",
  g = { {"onhygiënisch", "unsanitary"}, {"onuitsprekelijk", "unspeakable"}, {"bloederige", "bloody (bloederig)"}, {"trofee", "trophy"}, {"laten zien", "shown (laten zien)"}, {"zorg ervoor", "take care of it (zorgen voor)"}, {"wraak nemen op", "get back at"}, {"verwaande", "snooty (verwaand)"}, {"arrogante", "stuck-up, arrogant (arrogant)"}, {"aardig", "pretty, quite"}, {"verdiend", "earned (verdienen)"} },
},

[256] = { en = "WANTED: Chok'sul", tier = 2,
  t = "GEZOCHT: Chok'sul",
  d = "In opdracht van de magistraat van Thelsamar:$b$bChok'sul is de oger die waarschijnlijk de aanvallen op de stad Thelsamar, de Stonewrought Dam en de opgraving leidt en organiseert. Hij wordt dood gezocht, op elke manier die nodig is.$b$bWie de magistraat bewijs brengt van de dood van Chok'sul, krijgt een beloning in geld.$b$bChok'sul is het laatst gezien bij het kamp van de ogers in het noordoosten van Loch Modan.",
  o = "Dood Chok'sul en breng zijn hoofd naar Magistrate Bluntnose van Thelsamar.",
  p = "Ja? Kan ik iets voor je doen?",
  c = "Gadver! Wat is dat ding? En waarom zou je het...$b$bVerdorie--! Is het...? Nou, het Licht mag me verbranden, is dat het hoofd van die vervloekte oger? Dan is dit echt een mooie vangst! Hier, je beloning, en de dank van mij en de mensen van Thelsamar.",
  g = { {"gezocht", "wanted (zoeken)"}, {"in opdracht van", "by order of"}, {"magistraat", "magistrate"}, {"waarschijnlijk", "presumably, probably"}, {"organiseert", "coordinates, organizes (organiseren)"}, {"bewijs", "proof"}, {"beloning", "reward, compensation"}, {"het laatst gezien", "last seen"}, {"gadver", "yuck"}, {"verdorie", "blast, bloody"}, {"verbranden", "burn"}, {"vangst", "catch"} },
},

})

